window.NEN=[{"id": "ielts-tong-quan", "group": "Tổng quan", "title": "Làm quen IELTS Academic", "level": 1, "mins": 10, "why": "Hiểu rõ 4 kỹ năng, thời gian và cách tính band giúp bạn đặt mục tiêu thực tế (ví dụ 5.5 hay 6.5) và biết nên dồn sức vào kỹ năng nào.", "sections": [{"h": "4 kỹ năng và thời gian", "html": "<table>\n<tr><th>Kỹ năng</th><th>Thời gian</th><th>Cấu trúc</th></tr>\n<tr><td><b>Listening</b></td><td>khoảng 30 phút</td><td>4 phần (Part 1–4), 40 câu. Thi giấy có thêm 10 phút chép đáp án; thi máy có khoảng 2 phút để kiểm tra.</td></tr>\n<tr><td><b>Reading</b></td><td>60 phút</td><td>3 bài đọc dài, 40 câu. <b>Không</b> có thêm giờ chép đáp án.</td></tr>\n<tr><td><b>Writing</b></td><td>60 phút</td><td>Task 1 (ít nhất 150 từ, mô tả biểu đồ) + Task 2 (ít nhất 250 từ, bài luận). Task 2 được tính điểm gấp đôi Task 1.</td></tr>\n<tr><td><b>Speaking</b></td><td>11–14 phút</td><td>Nói trực tiếp với giám khảo, 3 phần (Part 1, 2, 3).</td></tr>\n</table>\n<div class=\"note\">Listening, Reading, Writing thường thi liền nhau trong một buổi. Speaking có thể cùng ngày hoặc khác ngày.</div>"}, {"h": "Cách tính band tổng (Overall)", "html": "<p>Mỗi kỹ năng được chấm từ 0 đến 9 (có nửa band như 5.5, 6.5). <b>Band tổng = trung bình cộng 4 kỹ năng, làm tròn đến 0.5 gần nhất.</b></p>\n<table>\n<tr><th>Trung bình có đuôi</th><th>Làm tròn thành</th><th>Ví dụ</th></tr>\n<tr><td>.25</td><td>lên .5</td><td>6.25 → <b>6.5</b></td></tr>\n<tr><td>.75</td><td>lên số nguyên kế tiếp</td><td>5.75 → <b>6.0</b></td></tr>\n<tr><td>dưới .25 (ví dụ .125)</td><td>xuống số nguyên</td><td>6.125 → <b>6.0</b></td></tr>\n<tr><td>từ .5 đến dưới .75 (ví dụ .625)</td><td>xuống .5</td><td>5.625 → <b>5.5</b></td></tr>\n</table>\n<div class=\"ex\">L 6.5 + R 6.0 + W 5.5 + S 6.0 = 24.0 → 24.0 ÷ 4 = 6.0 → <b>Overall 6.0</b><br>L 7.0 + R 6.5 + W 5.5 + S 6.0 = 25.0 → 25.0 ÷ 4 = 6.25 → <b>Overall 6.5</b></div>"}, {"h": "Quy đổi số câu đúng → band Listening (ước lượng)", "html": "<table>\n<tr><th>Số câu đúng / 40</th><th>Band (ước lượng)</th></tr>\n<tr><td>39–40</td><td>9.0</td></tr>\n<tr><td>37–38</td><td>8.5</td></tr>\n<tr><td>35–36</td><td>8.0</td></tr>\n<tr><td>32–34</td><td>7.5</td></tr>\n<tr><td>30–31</td><td>7.0</td></tr>\n<tr><td>26–29</td><td>6.5</td></tr>\n<tr><td>23–25</td><td>6.0</td></tr>\n<tr><td>18–22</td><td>5.5</td></tr>\n<tr><td>16–17</td><td>5.0</td></tr>\n<tr><td>13–15</td><td>4.5</td></tr>\n</table>\n<div class=\"note\">Đây chỉ là bảng <b>ước lượng</b> để tự luyện. Mức quy đổi thật có thể chênh 1–2 câu tùy đề. Reading Academic có bảng riêng, gần giống bảng này.</div>"}], "tips": ["Mục tiêu 6.0 nghĩa là Listening chỉ cần khoảng 23–25/40 câu đúng, không cần hoàn hảo.", "Writing thường là kỹ năng thấp nhất của người Việt; kéo Listening và Reading lên cao sẽ bù lại band tổng.", "Không có điểm trừ khi sai, nên đừng bao giờ bỏ trống câu nào trong Listening và Reading."], "mistakes": ["Nghĩ rằng band tổng chỉ làm tròn xuống. Thật ra 6.25 được làm tròn LÊN 6.5, và 5.75 lên 6.0.", "Dành quá nhiều thời gian cho Writing Task 1. Task 2 được tính gấp đôi, nên hãy dành khoảng 40 phút cho Task 2.", "Quên rằng Reading không có thêm giờ chép đáp án, dẫn đến hết giờ mà chưa điền phiếu."], "quiz": [{"q": "Một học viên được: Listening 7.0, Reading 6.5, Writing 5.5, Speaking 6.0. Band tổng là bao nhiêu?", "opts": ["6.0", "6.25", "6.5", "7.0"], "a": 2, "ex": "Tổng = 25.0, chia 4 = 6.25. Đuôi .25 được làm tròn lên .5, nên band tổng là 6.5. Không có band 6.25."}, {"q": "Điểm 4 kỹ năng là 6.0, 6.0, 5.5, 5.5. Band tổng là?", "opts": ["6.0", "5.5", "5.75", "6.5"], "a": 0, "ex": "Tổng = 23.0, chia 4 = 5.75. Đuôi .75 được làm tròn lên số nguyên kế tiếp, nên là 6.0."}, {"q": "Điểm 4 kỹ năng là 7.0, 6.0, 6.0, 5.5. Band tổng là?", "opts": ["6.5", "6.0", "6.25", "5.5"], "a": 1, "ex": "Tổng = 24.5, chia 4 = 6.125. Đuôi .125 nhỏ hơn .25 nên làm tròn xuống 6.0."}, {"q": "Bạn làm đúng 30/40 câu Listening. Band ước lượng là?", "opts": ["6.0", "6.5", "7.5", "7.0"], "a": 3, "ex": "Theo bảng ước lượng, 30–31 câu đúng tương đương khoảng band 7.0."}, {"q": "Phần Reading của IELTS Academic kéo dài bao lâu?", "opts": ["40 phút", "60 phút", "30 phút", "90 phút"], "a": 1, "ex": "Reading có 60 phút cho 3 bài đọc và 40 câu, không có thêm thời gian chép đáp án."}, {"q": "Trong Writing, phần nào chiếm nhiều điểm hơn?", "opts": ["Task 1, vì làm trước", "Hai task bằng nhau", "Tùy giám khảo chọn", "Task 2, vì được tính gấp đôi Task 1"], "a": 3, "ex": "Task 2 được tính điểm gấp đôi Task 1, nên nên dành khoảng 40 phút cho Task 2 và 20 phút cho Task 1."}, {"q": "Trong Speaking Part 2, bạn có bao nhiêu thời gian chuẩn bị trước khi nói?", "opts": ["1 phút", "Không có thời gian chuẩn bị", "5 phút", "10 giây"], "a": 0, "ex": "Giám khảo đưa thẻ đề, bạn có 1 phút để ghi chú rồi nói khoảng 1–2 phút."}, {"q": "Bạn muốn Listening đạt khoảng 6.0. Theo bảng ước lượng, bạn cần đúng khoảng bao nhiêu câu?", "opts": ["16–17 câu", "30–31 câu", "23–25 câu", "37–38 câu"], "a": 2, "ex": "Band 6.0 tương đương khoảng 23–25/40 câu đúng."}]}, {"id": "ielts-listening-chinh-ta-so", "group": "Nghe", "title": "Chính tả, số, chữ cái và ngày tháng", "level": 1, "mins": 12, "why": "Listening Part 1 (và nhiều câu ở Part 2–4) yêu cầu điền tên, số điện thoại, ngày tháng. Nghe đúng nhưng viết sai chính tả hay sai giới hạn từ vẫn bị tính sai.", "sections": [{"h": "Bảng chữ cái dễ nhầm", "html": "<table>\n<tr><th>Chữ cái</th><th>Đọc gần giống</th><th>Hay nhầm với</th></tr>\n<tr><td><b>A</b></td><td>/eɪ/ \"ây\"</td><td>E, I</td></tr>\n<tr><td><b>E</b></td><td>/iː/ \"ii\"</td><td>I (vì tiếng Việt \"i\")</td></tr>\n<tr><td><b>I</b></td><td>/aɪ/ \"ai\"</td><td>E</td></tr>\n<tr><td><b>G</b></td><td>/dʒiː/ \"gi\"</td><td>J</td></tr>\n<tr><td><b>J</b></td><td>/dʒeɪ/ \"giây\"</td><td>G</td></tr>\n<tr><td><b>R</b></td><td>/ɑː/ \"a\"</td><td>A</td></tr>\n<tr><td><b>Y</b></td><td>/waɪ/ \"quai\"</td><td>I</td></tr>\n<tr><td><b>W</b></td><td>\"đấp-bồ-yu\"</td><td>V</td></tr>\n</table>\n<div class=\"ex\"><span class=\"en\">\"It's P-A-double R-Y.\"</span> → <b>Parry</b><br><span class=\"vi\">\"double R\" = hai chữ R liền nhau</span></div>"}, {"h": "Số và số điện thoại", "html": "<ul>\n<li><b>0</b> thường được đọc là <span class=\"en\">\"oh\"</span> hoặc <span class=\"en\">\"zero\"</span>.</li>\n<li><span class=\"en\">\"double five\"</span> = 55, <span class=\"en\">\"triple two\"</span> = 222.</li>\n<li>Số đuôi <b>-teen</b> nhấn ở cuối: four<b>TEEN</b> (14). Số đuôi <b>-ty</b> nhấn ở đầu: <b>FOR</b>ty (40).</li>\n<li>Giá tiền: <span class=\"en\">\"nine pounds fifty\"</span> → <b>9.50</b></li>\n</ul>\n<div class=\"ex\"><span class=\"en\">\"My number is oh-seven-double-four, six-two-one.\"</span> → <b>0744 621</b></div>"}, {"h": "Ngày tháng", "html": "<table>\n<tr><th>Bạn nghe</th><th>Viết được</th></tr>\n<tr><td><span class=\"en\">the third of May</span></td><td>3 May / May 3 / 3rd May</td></tr>\n<tr><td><span class=\"en\">August the twenty-second</span></td><td>22 August / August 22</td></tr>\n</table>\n<div class=\"note\">Nhớ chính tả các tháng: Feb<b>r</b>uary, Wedne<b>s</b>day, Augu<b>st</b>. Viết tháng sai chính tả là mất điểm.</div>"}, {"h": "Giới hạn từ (word limit)", "html": "<table>\n<tr><th>Đề ghi</th><th>Được phép</th><th>Ví dụ hợp lệ</th></tr>\n<tr><td>ONE WORD ONLY</td><td>1 từ</td><td>library</td></tr>\n<tr><td>NO MORE THAN TWO WORDS</td><td>tối đa 2 từ</td><td>city library</td></tr>\n<tr><td>ONE WORD AND/OR A NUMBER</td><td>1 từ, hoặc 1 số, hoặc 1 từ + 1 số</td><td>15 / Monday / 15 Monday</td></tr>\n</table>\n<div class=\"ex\">Đề: NO MORE THAN TWO WORDS. Nghe: <span class=\"en\">\"in the old city library\"</span><br>Viết <b>city library</b> hoặc <b>library</b>, KHÔNG viết \"the old city library\" (4 từ → sai).</div>"}], "tips": ["Trước khi nghe, đọc đề xem chỗ trống cần tên, số hay ngày để chuẩn bị tinh thần.", "Khi nghe đánh vần, viết từng chữ cái ra nháp thật nhanh, nghe xong mới ghép lại.", "Chữ hoa hay chữ thường đều được chấp nhận, nhưng sai chính tả hoặc thiếu 's' số nhiều thì bị tính sai."], "mistakes": ["Nhầm E và I: tiếng Việt đọc 'i' cho cả hai. Hãy nhớ E = /iː/ 'ii', I = /aɪ/ 'ai'.", "Quên 'double': nghe 'double L' nhưng chỉ viết một chữ L. Fix: thấy 'double' là viết ngay 2 chữ.", "Viết quá giới hạn từ (thêm 'the', 'a', tính từ thừa). Fix: luôn đếm lại số từ trước khi chuyển đáp án.", "Nhầm 15 và 50, 13 và 30. Fix: chú ý trọng âm, -TEEN nhấn ở cuối và âm kéo dài hơn."], "quiz": [{"q": "Bạn nghe: \"My surname is K-E-double L-Y.\" Viết gì?", "opts": ["Kely", "Kelly", "Kellie", "Keli"], "a": 1, "ex": "'double L' = LL, nên tên là K-E-L-L-Y = Kelly."}, {"q": "Bạn nghe: \"oh-seven-double-nine, three-five-oh\". Số điện thoại là?", "opts": ["0799 350", "0709 935", "7099 350", "0799 305"], "a": 0, "ex": "'oh' = 0, 'double nine' = 99, nên là 0-7-9-9, rồi 3-5-0: 0799 350."}, {"q": "Người nói nhấn mạnh âm cuối và kéo dài: \"fif-TEEN people\". Đó là số mấy?", "opts": ["50", "5", "15", "150"], "a": 2, "ex": "Số đuôi -teen nhấn ở âm cuối (fifTEEN = 15). Còn FIFty (50) nhấn ở âm đầu."}, {"q": "Bạn nghe một chữ cái được đọc là /iː/ (giống 'ii' kéo dài). Đó là chữ nào?", "opts": ["I", "A", "Y", "E"], "a": 3, "ex": "Chữ E đọc là /iː/. Chữ I đọc là /aɪ/ 'ai', chữ A đọc là /eɪ/ 'ây'."}, {"q": "Đề ghi NO MORE THAN TWO WORDS. Đáp án nào KHÔNG hợp lệ?", "opts": ["library", "city library", "the old city library", "Library"], "a": 2, "ex": "'the old city library' có 4 từ, vượt giới hạn 2 từ nên bị tính sai dù nội dung đúng. Chữ hoa hay thường đều được chấp nhận."}, {"q": "Bạn nghe: \"The course starts on the twenty-first of March.\" Viết gì?", "opts": ["20 March", "1 March", "21 March", "12 March"], "a": 2, "ex": "'twenty-first' = 21, nên viết 21 March (hoặc March 21)."}, {"q": "Đề: Price: £____ (ONE WORD AND/OR A NUMBER). Bạn nghe: \"twelve pounds fifty\". Viết gì?", "opts": ["12.50", "twelve pounds fifty", "12.5 pounds", "1250"], "a": 0, "ex": "'twelve pounds fifty' = 12.50. Viết bằng số là gọn và đúng giới hạn. 'twelve pounds fifty' là 3 từ, '12.5 pounds' thừa chữ 'pounds' vì đề đã có ký hiệu £."}, {"q": "Bạn nghe một chữ cái đọc là /dʒeɪ/ (gần giống 'giây'). Đó là chữ nào?", "opts": ["G", "Y", "A", "J"], "a": 3, "ex": "J đọc là /dʒeɪ/. G đọc là /dʒiː/ 'gi'. Đây là cặp người Việt rất hay nhầm."}]}, {"id": "ielts-listening-tu-bao-hieu-bay", "group": "Nghe", "title": "Từ báo hiệu và bẫy đổi ý", "level": 2, "mins": 12, "why": "Đề Listening thường cố tình nói một đáp án rồi sửa lại (bẫy đổi ý), đặc biệt ở Part 1 và Part 2. Nhận ra từ báo hiệu giúp bạn không chọn nhầm đáp án đầu tiên nghe được.", "sections": [{"h": "Từ báo hiệu đổi ý", "html": "<table>\n<tr><th>Từ báo hiệu</th><th>Ý nghĩa</th><th>Ví dụ</th></tr>\n<tr><td><span class=\"en\">sorry, I mean...</span></td><td>sửa lại lời vừa nói</td><td><span class=\"en\">It's on the 5th... sorry, I mean the 6th.</span> → <b>6th</b></td></tr>\n<tr><td><span class=\"en\">actually</span></td><td>thật ra (thông tin đúng nằm sau)</td><td><span class=\"en\">I thought it was £20, but actually it's £25.</span> → <b>£25</b></td></tr>\n<tr><td><span class=\"en\">however / but</span></td><td>tuy nhiên (đổi hướng)</td><td><span class=\"en\">The gym usually closes at 9. However, on Sundays it closes at 6.</span></td></tr>\n<tr><td><span class=\"en\">in the end / finally</span></td><td>cuối cùng (quyết định chốt)</td><td><span class=\"en\">We considered the hotel, but in the end we chose a hostel.</span> → <b>hostel</b></td></tr>\n<tr><td><span class=\"en\">no, wait / oh no</span></td><td>tự sửa</td><td><span class=\"en\">Room 12... no, wait, Room 21.</span> → <b>21</b></td></tr>\n</table>"}, {"h": "Từ báo hiệu chuyển ý (Part 2 và 4)", "html": "<ul>\n<li><span class=\"en\">First of all / To begin with</span> <span class=\"vi\">trước hết</span></li>\n<li><span class=\"en\">Moving on to... / Next</span> <span class=\"vi\">chuyển sang ý tiếp theo</span></li>\n<li><span class=\"en\">For example / such as</span> <span class=\"vi\">ví dụ</span></li>\n<li><span class=\"en\">The main reason is...</span> <span class=\"vi\">lý do chính là</span></li>\n<li><span class=\"en\">To sum up / Finally</span> <span class=\"vi\">tóm lại / cuối cùng</span></li>\n</ul>\n<div class=\"note\">Khi nghe \"Moving on to...\", hãy chuyển mắt sang câu hỏi tiếp theo. Đáp án thường xuất hiện ngay sau đó.</div>"}, {"h": "Đoán loại từ trước khi nghe", "html": "<p>Trong 30 giây đọc đề, nhìn từ đứng trước và sau chỗ trống để đoán cần <b>danh từ, động từ, tính từ hay số</b>.</p>\n<table>\n<tr><th>Câu trong đề</th><th>Cần loại từ</th><th>Gợi ý</th></tr>\n<tr><td><span class=\"en\">The hotel offers free ____ for guests.</span></td><td>danh từ</td><td>sau tính từ \"free\"</td></tr>\n<tr><td><span class=\"en\">Visitors must ____ their bags.</span></td><td>động từ nguyên mẫu</td><td>sau \"must\"</td></tr>\n<tr><td><span class=\"en\">The rooms are very ____.</span></td><td>tính từ</td><td>sau \"very\"</td></tr>\n<tr><td><span class=\"en\">Cost: £____</span></td><td>số</td><td>có ký hiệu tiền</td></tr>\n</table>"}], "tips": ["Đừng viết vội đáp án đầu tiên nghe được. Chờ đến hết ý (đến khi người nói chuyển sang chuyện khác).", "Gạch chân từ khóa trong câu hỏi và đoán trước từ đồng nghĩa người nói có thể dùng.", "Nếu lỡ một câu, bỏ qua ngay và tập trung nghe câu tiếp theo, đừng tiếc."], "mistakes": ["Chọn ngay con số đầu tiên nghe thấy, trong khi người nói sửa lại ngay sau đó. Fix: nghe kỹ 'sorry', 'actually', 'no, wait'.", "Chỉ chờ nghe đúng từ trong đề. Đề thường dùng từ đồng nghĩa (cheap → not expensive). Fix: đoán trước từ đồng nghĩa.", "Điền sai loại từ (điền động từ vào chỗ cần danh từ). Fix: đoán loại từ trước khi nghe và kiểm tra ngữ pháp sau khi điền."], "quiz": [{"q": "Bạn nghe: \"The tour starts at nine... sorry, I mean half past nine.\" Tour bắt đầu lúc mấy giờ?", "opts": ["9.00", "9.30", "9.15", "Không rõ"], "a": 1, "ex": "'sorry, I mean' báo hiệu người nói sửa lại. Thông tin đúng là half past nine = 9.30."}, {"q": "Bạn nghe: \"We usually meet on Tuesdays, but this month it's actually on Thursdays.\" Tháng này họ gặp vào thứ mấy?", "opts": ["Thursday", "Tuesday", "Monday", "Wednesday"], "a": 0, "ex": "'but... actually' cho biết thông tin mới thay cho thói quen cũ. Tháng này họ gặp vào Thursday."}, {"q": "Đề: \"The hotel offers free ____ for guests.\" Chỗ trống cần loại từ nào?", "opts": ["Động từ (verb)", "Tính từ (adjective)", "Danh từ (noun)", "Trạng từ (adverb)"], "a": 2, "ex": "Sau tính từ 'free' cần một danh từ, ví dụ 'parking' hoặc 'breakfast'."}, {"q": "Đề: \"Visitors must ____ their bags at the front desk.\" Chỗ trống cần gì?", "opts": ["Danh từ số nhiều", "Tính từ", "Động từ thêm -ing", "Động từ nguyên mẫu"], "a": 3, "ex": "Sau động từ khuyết thiếu 'must' luôn là động từ nguyên mẫu, ví dụ 'leave'."}, {"q": "Từ nào thường báo hiệu thông tin trái ngược / đổi hướng?", "opts": ["also", "however", "and", "for example"], "a": 1, "ex": "'however' (tuy nhiên) báo hiệu thông tin trái với ý trước. 'also' và 'and' là thêm ý, 'for example' là ví dụ."}, {"q": "Bạn nghe: \"I was going to take the bus, but in the end I drove.\" Người này đi bằng gì?", "opts": ["by train", "on foot", "by car", "by bus"], "a": 2, "ex": "'in the end' báo hiệu quyết định cuối cùng: 'I drove' = lái xe, tức là by car. Bus chỉ là dự định ban đầu (bẫy)."}, {"q": "Đề: \"Number of people: ____\". Bạn nghe: \"There'll be twelve of us... oh no, two people cancelled, so ten.\" Điền gì?", "opts": ["12", "10", "2", "14"], "a": 1, "ex": "Ban đầu là 12, nhưng 2 người hủy nên còn 10. 'oh no' báo hiệu thay đổi."}, {"q": "Trong bài nói Part 4, người nói dùng \"Moving on to...\". Cụm này báo hiệu điều gì?", "opts": ["Nhắc lại ý cũ", "Đưa ra ví dụ", "Kết luận bài nói", "Chuyển sang ý mới"], "a": 3, "ex": "'Moving on to...' = chuyển sang phần/ý tiếp theo. Đây là lúc nên nhìn sang câu hỏi kế tiếp."}]}, {"id": "ielts-reading-skim-scan", "group": "Đọc", "title": "Skimming, scanning và quản lý 60 phút", "level": 1, "mins": 10, "why": "Reading có 3 bài dài khoảng 700–900 từ mỗi bài trong 60 phút. Không thể đọc kỹ từng chữ, nên skimming và scanning là kỹ năng sống còn để kịp làm 40 câu.", "sections": [{"h": "Skimming và scanning khác nhau thế nào", "html": "<table>\n<tr><th></th><th>Skimming (đọc lướt)</th><th>Scanning (đọc quét)</th></tr>\n<tr><td>Mục đích</td><td>nắm <b>ý chính</b> của bài / đoạn</td><td>tìm <b>một thông tin cụ thể</b></td></tr>\n<tr><td>Cách làm</td><td>đọc câu đầu (và câu cuối) mỗi đoạn</td><td>đưa mắt tìm từ khóa, số, tên riêng, năm</td></tr>\n<tr><td>Dùng cho</td><td>Matching headings, câu hỏi ý chính</td><td>điền từ, TRUE/FALSE/NOT GIVEN, câu hỏi chi tiết</td></tr>\n</table>"}, {"h": "Từ khóa nào dễ scan nhất", "html": "<ul>\n<li><b>Số và năm:</b> <span class=\"en\">1998, 40%, 3 million</span></li>\n<li><b>Tên riêng (viết hoa):</b> <span class=\"en\">Dr Hansen, Brazil, the Nile</span></li>\n<li><b>Từ chuyên ngành ít gặp:</b> <span class=\"en\">photosynthesis, glacier</span></li>\n</ul>\n<div class=\"ex\">Câu hỏi: <span class=\"en\">In which year did the museum first open to the public?</span><br>→ Scan tìm con số 4 chữ số (năm) gần các từ <span class=\"en\">museum, open</span>.</div>"}, {"h": "Chia 60 phút", "html": "<table>\n<tr><th>Bài đọc</th><th>Thời gian gợi ý</th><th>Ghi chú</th></tr>\n<tr><td>Passage 1</td><td>17–18 phút</td><td>thường dễ nhất, làm nhanh để dư giờ</td></tr>\n<tr><td>Passage 2</td><td>20 phút</td><td></td></tr>\n<tr><td>Passage 3</td><td>22–23 phút</td><td>thường khó nhất</td></tr>\n</table>\n<div class=\"note\">Thi giấy: viết đáp án thẳng vào answer sheet ngay khi làm, vì Reading <b>không có thêm giờ</b> chép đáp án.</div>"}], "tips": ["Đọc câu hỏi trước, gạch chân từ khóa, rồi mới quay lại bài đọc.", "Một câu quá 2 phút chưa ra: đoán một đáp án, đánh dấu, làm tiếp. Không để trống câu nào.", "Dạng TRUE/FALSE/NOT GIVEN và điền từ thường đi theo thứ tự bài đọc: đáp án câu 2 thường nằm sau câu 1."], "mistakes": ["Đọc kỹ và dịch từng câu từ đầu bài. Fix: skim trước 2–3 phút để biết mỗi đoạn nói gì.", "Thấy đúng một từ giống câu hỏi là chọn ngay. Fix: đọc kỹ cả câu chứa từ khóa và câu xung quanh.", "Sa lầy ở Passage 1 rồi không kịp làm Passage 3. Fix: đeo đồng hồ, theo đúng thời gian cho từng bài."], "quiz": [{"q": "Bạn cần tìm năm 1998 trong bài đọc. Bạn dùng kỹ năng nào?", "opts": ["Skimming", "Scanning", "Đọc kỹ từng chữ", "Dịch cả bài"], "a": 1, "ex": "Tìm một thông tin cụ thể (con số, năm) là scanning: đưa mắt tìm nhanh con số đó."}, {"q": "Bạn muốn biết nhanh đoạn C nói về chủ đề gì. Cách nào hợp lý nhất?", "opts": ["Đọc câu đầu và câu cuối của đoạn C", "Tìm tất cả con số trong đoạn C", "Tra từ điển mọi từ mới", "Đọc lại toàn bộ bài từ đầu"], "a": 0, "ex": "Đây là skimming: câu đầu (và câu cuối) đoạn thường chứa ý chính."}, {"q": "Khi scan tìm tên một nhà khoa học, dấu hiệu nào giúp tìm nhanh nhất?", "opts": ["Từ 'the'", "Câu dài nhất đoạn", "Chữ viết hoa", "Dấu chấm câu"], "a": 2, "ex": "Tên riêng luôn viết hoa, nên mắt dễ bắt được khi quét."}, {"q": "Thi Reading trên giấy, bạn có thêm bao nhiêu phút để chép đáp án vào answer sheet?", "opts": ["10 phút", "5 phút", "2 phút", "Không có thêm phút nào"], "a": 3, "ex": "Khác với Listening, Reading không có thêm giờ. Hãy viết đáp án vào answer sheet ngay trong 60 phút."}, {"q": "Bạn làm một câu đã 3 phút mà chưa tìm ra đáp án. Nên làm gì?", "opts": ["Tiếp tục tìm đến khi ra", "Đoán một đáp án, đánh dấu, làm câu tiếp", "Bỏ trống câu đó", "Bỏ luôn cả bài đọc"], "a": 1, "ex": "Không bị trừ điểm khi sai, nên luôn đoán một đáp án. Đánh dấu để quay lại nếu còn giờ."}, {"q": "Dạng câu hỏi nào thường đi theo thứ tự của bài đọc?", "opts": ["TRUE/FALSE/NOT GIVEN", "Matching information (tìm đoạn chứa thông tin)", "Không dạng nào theo thứ tự"], "a": 0, "ex": "TRUE/FALSE/NOT GIVEN thường theo thứ tự bài đọc. Matching information thì không theo thứ tự, phải tìm khắp bài."}, {"q": "Câu hỏi: 'What percentage of the city's water comes from rivers?' Bạn nên scan tìm gì?", "opts": ["Một tên người", "Một con số kèm dấu % gần từ 'water' / 'rivers'", "Câu đầu tiên của bài", "Mọi tính từ trong bài"], "a": 1, "ex": "Câu hỏi hỏi phần trăm, nên scan tìm con số có % ở gần từ khóa 'water', 'rivers'."}, {"q": "Passage nào thường nên dành nhiều thời gian nhất?", "opts": ["Passage 1", "Passage 2", "Passage 3", "Chia đều chính xác 20 phút"], "a": 2, "ex": "Passage 3 thường khó nhất, nên làm Passage 1 nhanh để dư thời gian cho Passage 3."}]}, {"id": "ielts-reading-tfng-ynng", "group": "Đọc", "title": "TRUE/FALSE/NOT GIVEN và YES/NO/NOT GIVEN", "level": 2, "mins": 14, "why": "Đây là dạng câu hỏi xuất hiện gần như trong mọi đề Reading và là dạng người Việt mất điểm nhiều nhất, chủ yếu do nhầm FALSE với NOT GIVEN.", "sections": [{"h": "Hai dạng khác nhau thế nào", "html": "<table>\n<tr><th>Dạng</th><th>Hỏi về</th><th>Đáp án</th></tr>\n<tr><td>TRUE / FALSE / NOT GIVEN</td><td><b>thông tin, sự thật</b> trong bài</td><td>TRUE = khớp; FALSE = trái ngược; NOT GIVEN = bài không nói</td></tr>\n<tr><td>YES / NO / NOT GIVEN</td><td><b>quan điểm, ý kiến của tác giả</b></td><td>YES = tác giả đồng ý; NO = tác giả phản đối; NOT GIVEN = tác giả không nêu ý kiến</td></tr>\n</table>\n<div class=\"note\">Cách chọn giống nhau. Chỉ khác: một bên hỏi sự thật, một bên hỏi ý kiến. Đừng viết YES vào câu TRUE/FALSE (và ngược lại), sẽ bị tính sai.</div>"}, {"h": "Phân biệt FALSE và NOT GIVEN", "html": "<p><b>FALSE:</b> bài đọc nói điều <b>ngược lại</b>, bạn chỉ ra được câu chứng minh câu hỏi sai.<br><b>NOT GIVEN:</b> bài đọc <b>không có thông tin</b> để khẳng định đúng hay sai.</p>\n<div class=\"ex\">Bài: <span class=\"en\">Most of the volunteers were university students.</span><br>Câu hỏi: <span class=\"en\">All of the volunteers were university students.</span> → <b>FALSE</b> <span class=\"vi\">(most ≠ all, trái ngược)</span><br><br>Câu hỏi: <span class=\"en\">The volunteers were paid for their work.</span> → <b>NOT GIVEN</b> <span class=\"vi\">(bài không nói gì về tiền công)</span></div>\n<p>Tự hỏi: <i>\"Có câu nào trong bài nói ngược lại không?\"</i> Có → FALSE. Không có gì để so → NOT GIVEN.</p>"}, {"h": "Từ khóa hay gây bẫy", "html": "<table>\n<tr><th>Loại</th><th>Ví dụ</th><th>Cần kiểm tra</th></tr>\n<tr><td>Mức độ</td><td><span class=\"en\">all / most / some / never / always</span></td><td>bài có cùng mức độ không?</td></tr>\n<tr><td>So sánh</td><td><span class=\"en\">more than, the largest, the first</span></td><td>bài có thật sự so sánh không?</td></tr>\n<tr><td>Lý do</td><td><span class=\"en\">because, due to</span></td><td>bài có nêu nguyên nhân không? Nếu không → thường NOT GIVEN</td></tr>\n</table>"}], "tips": ["Gạch chân các từ chỉ mức độ (all, some, only, always) trong câu hỏi: đây là nơi đề hay đặt bẫy.", "Chỉ dùng thông tin trong bài, không dùng kiến thức bên ngoài dù bạn biết điều đó đúng ngoài đời.", "Câu hỏi đi theo thứ tự bài đọc: nếu tìm mãi không thấy thông tin giữa đáp án câu trước và câu sau, khả năng cao là NOT GIVEN."], "mistakes": ["Chọn FALSE chỉ vì bài không nhắc tới. Fix: không có thông tin = NOT GIVEN, chỉ chọn FALSE khi bài nói ngược lại.", "Dùng hiểu biết cá nhân ('ai cũng biết cà phê có caffeine') để chọn TRUE. Fix: chỉ dựa vào chữ trong bài.", "Viết T/F/NG cho dạng YES/NO/NOT GIVEN. Fix: đọc kỹ hướng dẫn và viết đúng loại đáp án đề yêu cầu."], "quiz": [{"q": "Bài: 'The library opens at 8 a.m. on weekdays.' Câu hỏi: 'The library opens at 8 a.m. from Monday to Friday.'", "opts": ["TRUE", "FALSE", "NOT GIVEN"], "a": 0, "ex": "'weekdays' = các ngày trong tuần (Monday to Friday). Hai câu cùng ý, nên TRUE."}, {"q": "Bài: 'Most of the volunteers were university students.' Câu hỏi: 'All of the volunteers were university students.'", "opts": ["TRUE", "FALSE", "NOT GIVEN"], "a": 1, "ex": "'Most' (hầu hết) khác 'All' (tất cả). Bài cho thấy chỉ hầu hết (không phải tất cả) tình nguyện viên là sinh viên đại học, nên câu hỏi trái với bài: FALSE."}, {"q": "Bài: 'The bridge was completed in 2015.' Câu hỏi: 'The bridge cost more than planned.'", "opts": ["TRUE", "FALSE", "NOT GIVEN"], "a": 2, "ex": "Bài chỉ nói năm hoàn thành, không nói gì về chi phí. Không có thông tin để so, nên NOT GIVEN."}, {"q": "Bài: 'Coffee was first grown in this region in the 1800s.' Câu hỏi: 'Coffee is the region's most profitable crop today.'", "opts": ["TRUE", "FALSE", "NOT GIVEN"], "a": 2, "ex": "Bài nói về thời điểm bắt đầu trồng, không nói cà phê có lãi nhất hiện nay hay không. NOT GIVEN."}, {"q": "Tác giả viết: 'In my view, online classes can never fully replace face-to-face teaching.' Câu hỏi: 'The writer believes online classes are just as good as traditional classes.'", "opts": ["YES", "NO", "NOT GIVEN"], "a": 1, "ex": "Tác giả cho rằng học online không thể thay thế hoàn toàn học trực tiếp, tức là không 'tốt ngang nhau'. Ý kiến trái ngược: NO."}, {"q": "Đề yêu cầu: 'Do the following statements agree with the views of the writer?' Bạn phải dùng bộ đáp án nào?", "opts": ["TRUE / FALSE / NOT GIVEN", "A / B / C / D", "YES / NO / NOT GIVEN"], "a": 2, "ex": "'views of the writer' = quan điểm của tác giả, nên dùng YES / NO / NOT GIVEN."}, {"q": "Bài: 'Sales fell slightly in 2020.' Câu hỏi: 'Sales rose in 2020.'", "opts": ["TRUE", "FALSE", "NOT GIVEN"], "a": 1, "ex": "Bài nói doanh số giảm (fell), câu hỏi nói tăng (rose). Trái ngược hoàn toàn: FALSE."}, {"q": "Bài: 'The company hired 50 new staff last year.' Câu hỏi: 'The company hired new staff last year because its sales increased.'", "opts": ["TRUE", "FALSE", "NOT GIVEN"], "a": 2, "ex": "Bài xác nhận việc tuyển người nhưng không nói lý do. Phần 'because its sales increased' không có trong bài, nên NOT GIVEN."}]}, {"id": "ielts-reading-matching", "group": "Đọc", "title": "Matching headings và matching information", "level": 2, "mins": 14, "why": "Matching headings (chọn tiêu đề cho đoạn) và matching information (tìm đoạn chứa thông tin) rất hay xuất hiện ở Passage 2 và 3, mỗi dạng thường chiếm 5–7 câu.", "sections": [{"h": "Matching headings: chọn tiêu đề cho đoạn", "html": "<p>Đề cho danh sách tiêu đề (i, ii, iii...) và bạn chọn tiêu đề phù hợp với <b>ý chính của cả đoạn</b>.</p>\n<ol>\n<li>Đọc lướt danh sách tiêu đề, gạch chân từ khóa.</li>\n<li>Đọc câu đầu và câu cuối của đoạn (skim). Chú ý từ đổi hướng như <span class=\"en\">However, But</span>: ý chính thường nằm sau.</li>\n<li>Chọn tiêu đề tóm tắt <b>cả đoạn</b>, không phải một chi tiết nhỏ.</li>\n</ol>\n<div class=\"note\">Số tiêu đề luôn nhiều hơn số đoạn, nên sẽ có tiêu đề không dùng đến.</div>"}, {"h": "Bẫy thường gặp", "html": "<div class=\"ex\">Đoạn: <span class=\"en\">Many cities now offer bike-sharing schemes. However, they are expensive to run: bikes are often stolen or damaged and need regular repair.</span><br><br>Tiêu đề bẫy: <span class=\"en\">How to repair a bicycle</span> <span class=\"vi\">(chỉ lấy một từ \"repair\")</span><br>Tiêu đề đúng: <span class=\"en\">The hidden costs of bike-sharing</span> <span class=\"vi\">(ý chính sau \"However\")</span></div>\n<p>Tiêu đề lặp đúng một từ trong đoạn thường là <b>bẫy</b>. Tiêu đề đúng thường dùng từ đồng nghĩa (<span class=\"en\">expensive</span> → <span class=\"en\">costs</span>).</p>"}, {"h": "Matching information: thông tin nằm ở đoạn nào", "html": "<p>Câu hỏi kiểu: <span class=\"en\">Which paragraph contains a reference to...</span> / <span class=\"en\">a description of...</span> / <span class=\"en\">an example of...</span></p>\n<table>\n<tr><th>Cụm trong câu hỏi</th><th>Cần tìm trong bài</th></tr>\n<tr><td><span class=\"en\">a reference to a cost</span></td><td>tiền, giá, $, expensive</td></tr>\n<tr><td><span class=\"en\">a future plan</span></td><td>will, plan to, hope to</td></tr>\n<tr><td><span class=\"en\">a comparison</span></td><td>more than, unlike, while</td></tr>\n</table>\n<div class=\"note\">Dạng này <b>không theo thứ tự</b> bài đọc và thông tin chỉ là một chi tiết nhỏ. Nếu đề ghi <span class=\"en\">You may use any letter more than once</span>, một đoạn có thể là đáp án cho nhiều câu.</div>"}], "tips": ["Matching headings: làm trước các đoạn ngắn hoặc dễ, loại dần tiêu đề đã dùng.", "Matching information: nên làm sau cùng, khi bạn đã quen bài đọc nhờ làm các dạng khác.", "Nếu đề có ví dụ (Example: Paragraph A → iv), gạch bỏ tiêu đề đó ngay."], "mistakes": ["Chọn tiêu đề vì thấy cùng một từ với đoạn. Fix: hỏi 'tiêu đề này có tóm tắt được CẢ đoạn không?'.", "Chỉ đọc câu đầu rồi chọn, bỏ qua 'However' ở giữa đoạn. Fix: luôn đọc thêm câu sau từ đổi hướng.", "Nghĩ mỗi đoạn chỉ dùng một lần trong matching information. Fix: đọc kỹ hướng dẫn 'more than once'."], "quiz": [{"q": "Đoạn: 'Many cities now offer bike-sharing schemes. However, they are expensive to run: bikes are often stolen or damaged and need regular repair.' Tiêu đề phù hợp nhất?", "opts": ["The hidden costs of bike-sharing", "Why people love cycling", "A short history of the bicycle", "How to repair a bicycle"], "a": 0, "ex": "Ý chính nằm sau 'However': chi phí vận hành cao. 'How to repair a bicycle' là bẫy vì chỉ lặp lại từ 'repair'."}, {"q": "Đoạn: 'Scientists once believed that adults could not grow new brain cells. Recent studies, however, have shown that this does happen, especially during exercise.' Tiêu đề phù hợp nhất?", "opts": ["The dangers of exercise", "A change in scientific opinion", "How to become a scientist", "Why children learn faster"], "a": 1, "ex": "Đoạn nói các nhà khoa học từng tin một điều, nhưng nghiên cứu mới cho thấy điều ngược lại: quan điểm khoa học đã thay đổi."}, {"q": "Đề có 8 tiêu đề nhưng bài chỉ có 6 đoạn. Điều này có nghĩa là gì?", "opts": ["Đề bị lỗi", "Mỗi đoạn có 2 tiêu đề", "Có 2 tiêu đề không được dùng", "Phải dùng cả 8 tiêu đề"], "a": 2, "ex": "Matching headings luôn cho thừa tiêu đề để gây nhiễu. Sẽ có tiêu đề không phù hợp với đoạn nào."}, {"q": "Đề matching information ghi: 'You may use any letter more than once.' Nghĩa là gì?", "opts": ["Mỗi câu có nhiều đáp án", "Mỗi đoạn chỉ dùng một lần", "Có thể bỏ trống", "Một đoạn có thể là đáp án cho nhiều câu"], "a": 3, "ex": "'use any letter more than once' = một chữ cái (một đoạn) có thể dùng cho nhiều câu hỏi."}, {"q": "A: 'The festival began in 1990 with only 200 visitors.' B: 'Tickets now cost $40, double the price of ten years ago.' C: 'Organisers hope to move the event to a larger park.' Đoạn nào nhắc đến sự thay đổi giá?", "opts": ["A", "B", "C"], "a": 1, "ex": "Đoạn B nói vé giờ là $40, gấp đôi 10 năm trước: đó là sự thay đổi giá."}, {"q": "Dùng các đoạn A, B, C ở câu trước. Đoạn nào nhắc đến một kế hoạch tương lai?", "opts": ["A", "B", "C"], "a": 2, "ex": "'hope to move the event' (hy vọng chuyển lễ hội) là kế hoạch tương lai, nằm ở đoạn C."}, {"q": "So với matching headings, matching information khác ở điểm nào?", "opts": ["Thông tin cần tìm thường là một chi tiết nhỏ, không phải ý chính", "Luôn theo thứ tự bài đọc", "Không cần đọc bài", "Chỉ có ở Listening"], "a": 0, "ex": "Matching headings cần ý chính cả đoạn, còn matching information chỉ cần tìm một chi tiết, và không theo thứ tự."}]}, {"id": "ielts-writing-task1-bo-cuc", "group": "Viết", "title": "Writing Task 1: bố cục 4 đoạn", "level": 1, "mins": 12, "why": "Task 1 (ít nhất 150 từ, khoảng 20 phút) yêu cầu mô tả biểu đồ, bảng hoặc quy trình. Thiếu overview là lỗi phổ biến khiến điểm Task Achievement khó vượt band 5.", "sections": [{"h": "Bố cục chuẩn", "html": "<table>\n<tr><th>Đoạn</th><th>Nội dung</th><th>Độ dài</th></tr>\n<tr><td>1. Mở bài</td><td>Paraphrase (viết lại) câu đề bằng từ của mình</td><td>1 câu</td></tr>\n<tr><td>2. Overview</td><td>Xu hướng chính / điểm nổi bật nhất, <b>không có số liệu chi tiết</b></td><td>2 câu</td></tr>\n<tr><td>3. Thân bài 1</td><td>Nhóm số liệu thứ nhất, có số cụ thể</td><td>3–4 câu</td></tr>\n<tr><td>4. Thân bài 2</td><td>Nhóm số liệu thứ hai, có số cụ thể</td><td>3–4 câu</td></tr>\n</table>\n<div class=\"note\">Task 1 <b>không</b> cần kết luận và <b>không</b> nêu ý kiến cá nhân. Overview chính là phần tóm tắt quan trọng nhất.</div>"}, {"h": "Mở bài: paraphrase câu đề", "html": "<div class=\"ex\">Đề: <span class=\"en\">The chart shows the number of tourists visiting three countries between 2010 and 2020.</span><br>Mở bài: <span class=\"en\">The bar chart illustrates how many tourists travelled to three countries from 2010 to 2020.</span></div>\n<table>\n<tr><th>Từ trong đề</th><th>Thay bằng</th></tr>\n<tr><td>shows</td><td>illustrates / gives information about / compares</td></tr>\n<tr><td>the number of tourists</td><td>how many tourists</td></tr>\n<tr><td>between 2010 and 2020</td><td>from 2010 to 2020 / over a ten-year period</td></tr>\n</table>\n<div class=\"note\">Chép nguyên văn câu đề: những từ chép lại không được tính vào số từ của bạn.</div>"}, {"h": "Overview: nhìn bức tranh lớn", "html": "<p>Bắt đầu bằng <span class=\"en\">Overall,</span> và trả lời 1–2 câu hỏi: <i>Cái gì tăng/giảm? Cái gì lớn nhất/nhỏ nhất?</i></p>\n<div class=\"ex\"><span class=\"en\">Overall, the number of tourists rose in all three countries, and Thailand was the most popular destination throughout the period.</span><br><span class=\"vi\">Nhìn chung, số khách du lịch tăng ở cả 3 nước, và Thái Lan là điểm đến phổ biến nhất suốt giai đoạn.</span></div>"}], "tips": ["Dành 2–3 phút đầu để nhìn biểu đồ, tìm 2 đặc điểm chính cho overview trước khi viết.", "Chia thân bài theo nhóm hợp lý: nhóm tăng / nhóm giảm, hoặc năm đầu / năm cuối.", "Viết khoảng 160–190 từ là đủ, viết dài hơn không được cộng điểm mà còn mất thời gian cho Task 2."], "mistakes": ["Không có overview hoặc nhét số liệu chi tiết vào overview. Fix: overview chỉ nói xu hướng, không có con số.", "Chép y nguyên câu đề làm mở bài. Fix: đổi ít nhất động từ và một cụm từ (shows → illustrates).", "Nêu ý kiến hoặc giải thích lý do ('vì người ta thích đi du lịch'). Fix: Task 1 chỉ mô tả những gì có trong biểu đồ.", "Liệt kê mọi con số theo thứ tự. Fix: chọn số liệu nổi bật và so sánh chúng."], "quiz": [{"q": "Đoạn overview trong Task 1 nên chứa gì?", "opts": ["Mọi con số trong biểu đồ", "Xu hướng chính và điểm nổi bật, không có số liệu chi tiết", "Ý kiến cá nhân về chủ đề", "Lý do tại sao số liệu thay đổi"], "a": 1, "ex": "Overview tóm tắt bức tranh lớn: cái gì tăng/giảm, cái gì lớn nhất. Số liệu chi tiết để ở thân bài."}, {"q": "Câu nào paraphrase tốt nhất cho đề: 'The graph shows the percentage of households with internet access in 2000 and 2020.'?", "opts": ["The graph shows the percentage of households with internet access in 2000 and 2020.", "The line graph illustrates the proportion of homes that had internet access in 2000 and 2020.", "I think internet access is very important for households.", "Internet is popular."], "a": 1, "ex": "Câu B đổi 'shows' → 'illustrates', 'percentage' → 'proportion', 'households' → 'homes' mà giữ đúng nghĩa. Câu A chép nguyên văn, câu C nêu ý kiến, câu D quá chung."}, {"q": "Task 1 có cần nêu ý kiến cá nhân không?", "opts": ["Có, ở mở bài", "Có, ở kết luận", "Không, chỉ mô tả và so sánh số liệu", "Tùy loại biểu đồ"], "a": 2, "ex": "Task 1 chỉ mô tả thông tin trong biểu đồ. Ý kiến cá nhân là việc của Task 2."}, {"q": "Task 1 yêu cầu viết ít nhất bao nhiêu từ?", "opts": ["100 từ", "250 từ", "200 từ", "150 từ"], "a": 3, "ex": "Task 1 tối thiểu 150 từ. Task 2 tối thiểu 250 từ."}, {"q": "Câu nào là một câu overview?", "opts": ["Overall, coffee consumption increased steadily, while tea remained the least popular drink.", "In 2010, coffee consumption was 25%.", "The chart shows drinks in three years.", "I prefer coffee to tea."], "a": 0, "ex": "Câu A bắt đầu bằng 'Overall' và nêu xu hướng chung, không có số liệu. Câu B là chi tiết cho thân bài."}, {"q": "Thời gian gợi ý cho Writing Task 1 là bao lâu?", "opts": ["40 phút", "20 phút", "10 phút", "60 phút"], "a": 1, "ex": "Tổng Writing là 60 phút: khoảng 20 phút cho Task 1 và 40 phút cho Task 2 (Task 2 được tính điểm gấp đôi)."}, {"q": "Nếu mở bài chép nguyên văn câu đề, điều gì xảy ra?", "opts": ["Được cộng điểm vì chính xác", "Không ảnh hưởng gì", "Những từ chép lại không được tính vào số từ của bạn", "Bài bị hủy"], "a": 2, "ex": "Từ chép từ đề không được tính vào số từ, và giám khảo đánh giá thấp vốn từ của bạn. Hãy paraphrase."}, {"q": "Biểu đồ có 4 quốc gia: 2 nước tăng, 2 nước giảm. Cách chia thân bài nào hợp lý nhất?", "opts": ["Mỗi nước một đoạn, 4 đoạn thân bài", "Một đoạn duy nhất liệt kê tất cả", "Không cần thân bài, chỉ cần overview", "Thân bài 1: 2 nước tăng; Thân bài 2: 2 nước giảm"], "a": 3, "ex": "Nhóm số liệu có điểm chung vào cùng một đoạn giúp bài rõ ràng và dễ so sánh."}]}, {"id": "ielts-writing-xu-huong-so-lieu", "group": "Viết", "title": "Ngôn ngữ mô tả xu hướng và số liệu", "level": 1, "mins": 14, "why": "Writing Task 1 dạng biểu đồ đường, cột, bảng luôn cần mô tả tăng, giảm, dao động. Dùng đúng động từ, trạng từ và giới từ giúp tăng điểm Lexical Resource và Grammatical Range.", "sections": [{"h": "Động từ và danh từ chỉ xu hướng", "html": "<table>\n<tr><th>Xu hướng</th><th>Động từ</th><th>Danh từ</th></tr>\n<tr><td>Tăng</td><td>rise, increase, grow, climb</td><td>a rise, an increase, growth</td></tr>\n<tr><td>Giảm</td><td>fall, decrease, decline, drop</td><td>a fall, a decrease, a decline, a drop</td></tr>\n<tr><td>Lên xuống thất thường</td><td>fluctuate</td><td>a fluctuation</td></tr>\n<tr><td>Giữ nguyên</td><td>remain stable, stay the same, level off</td><td>stability</td></tr>\n<tr><td>Đạt đỉnh</td><td>peak, reach a peak (of...)</td><td>a peak</td></tr>\n<tr><td>Chạm đáy</td><td>hit a low (of...)</td><td>a low</td></tr>\n</table>\n<div class=\"note\">Quá khứ hay gặp: rise → <b>rose</b>, fall → <b>fell</b>, grow → <b>grew</b>. Dữ liệu năm đã qua → dùng thì quá khứ đơn.</div>"}, {"h": "Mức độ thay đổi", "html": "<table>\n<tr><th>Mức độ</th><th>Trạng từ (+ động từ)</th><th>Tính từ (+ danh từ)</th></tr>\n<tr><td>Rất ít</td><td>slightly</td><td>a slight rise</td></tr>\n<tr><td>Đều đặn</td><td>gradually, steadily</td><td>a gradual / steady fall</td></tr>\n<tr><td>Đáng kể</td><td>significantly, considerably</td><td>a significant increase</td></tr>\n<tr><td>Mạnh, đột ngột</td><td>sharply, dramatically</td><td>a sharp / dramatic drop</td></tr>\n</table>\n<div class=\"ex\"><span class=\"en\">Sales rose sharply.</span> = <span class=\"en\">There was a sharp rise in sales.</span><br><span class=\"vi\">Doanh số tăng mạnh.</span></div>"}, {"h": "Giới từ và số liệu xấp xỉ", "html": "<table>\n<tr><th>Cấu trúc</th><th>Ví dụ</th><th>Nghĩa</th></tr>\n<tr><td>from A to B</td><td><span class=\"en\">rose from 20% to 35%</span></td><td>tăng từ 20% lên 35%</td></tr>\n<tr><td>by + mức thay đổi</td><td><span class=\"en\">rose by 15%</span></td><td>tăng thêm 15%</td></tr>\n<tr><td>stand at / at</td><td><span class=\"en\">stood at 40% in 2010</span></td><td>ở mức 40%</td></tr>\n<tr><td>approximately / around / roughly</td><td><span class=\"en\">approximately 3 million</span></td><td>khoảng 3 triệu</td></tr>\n<tr><td>just over / just under / nearly</td><td><span class=\"en\">just under half (49%)</span></td><td>gần một nửa</td></tr>\n</table>\n<p><b>the number of</b> + danh từ đếm được số nhiều (<span class=\"en\">the number of cars</span>); <b>the amount of</b> + danh từ không đếm được (<span class=\"en\">the amount of water</span>); <b>the proportion / percentage of</b> = tỷ lệ phần trăm (<span class=\"en\">the proportion of students who...</span>).</p>"}], "tips": ["Xen kẽ hai cấu trúc để đa dạng: 'X rose sharply' và 'There was a sharp rise in X'.", "Đổi số thành phân số khi hợp lý: 25% = a quarter, 50% = half, 75% = three quarters.", "Học thuộc 3 cặp: slightly/slight, sharply/sharp, gradually/gradual."], "mistakes": ["Dùng trạng từ trước danh từ: 'a sharply increase'. Fix: trước danh từ dùng tính từ → 'a sharp increase'.", "Nhầm 'to' và 'by': 'rose by 20%' (tăng thêm 20%) khác 'rose to 20%' (tăng lên mức 20%). Fix: 'by' = mức chênh, 'to' = mức cuối.", "Viết 'the number of water'. Fix: water không đếm được → 'the amount of water'.", "Dùng thì hiện tại cho dữ liệu năm 2010. Fix: năm đã qua → quá khứ đơn (rose, fell)."], "quiz": [{"q": "Tỷ lệ tăng từ 20% lên 21%. Trạng từ nào phù hợp nhất?", "opts": ["sharply", "dramatically", "slightly", "significantly"], "a": 2, "ex": "Chỉ tăng 1% là thay đổi rất nhỏ, nên dùng 'slightly'."}, {"q": "Doanh số tăng từ 10 lên 60 triệu chỉ trong một năm. Câu nào phù hợp?", "opts": ["Sales rose sharply.", "Sales remained stable.", "Sales fell slightly.", "Sales fluctuated."], "a": 0, "ex": "Tăng gấp 6 lần trong một năm là tăng rất mạnh: 'rose sharply'."}, {"q": "The number of cars rose ____ 200 ____ 500.", "opts": ["by / at", "from / to", "at / by", "to / from"], "a": 1, "ex": "'from A to B' = từ mức A lên mức B."}, {"q": "Prices increased ____ 10% (giá tăng thêm 10%).", "opts": ["to", "at", "from", "by"], "a": 3, "ex": "'by' chỉ mức chênh lệch: tăng THÊM 10%. 'to 10%' nghĩa là tăng LÊN mức 10%."}, {"q": "Số liệu lên rồi xuống, rồi lại lên liên tục. Động từ nào phù hợp?", "opts": ["fluctuated", "peaked", "remained stable", "declined"], "a": 0, "ex": "'fluctuate' = dao động, lên xuống thất thường."}, {"q": "The ____ of students who chose French fell in 2015.", "opts": ["amount", "number", "much", "level"], "a": 1, "ex": "'students' là danh từ đếm được số nhiều, nên dùng 'the number of'. 'amount of' dùng với danh từ không đếm được."}, {"q": "Con số 49% có thể được diễn đạt là gì?", "opts": ["just over half", "exactly half", "just under half", "a quarter"], "a": 2, "ex": "49% thấp hơn 50% một chút, nên là 'just under half' (dưới một nửa một chút)."}, {"q": "There was a ____ increase in the price of rice.", "opts": ["sharply", "sharp", "sharpen", "sharpness"], "a": 1, "ex": "Trước danh từ 'increase' cần tính từ: 'a sharp increase'. 'sharply' là trạng từ, dùng sau động từ (increased sharply)."}]}, {"id": "ielts-writing-task2-dang-de", "group": "Viết", "title": "Writing Task 2: các dạng đề và bố cục 4 đoạn", "level": 2, "mins": 15, "why": "Task 2 (ít nhất 250 từ, khoảng 40 phút) chiếm 2/3 điểm Writing. Xác định sai dạng đề dẫn đến trả lời lệch câu hỏi, và điểm Task Response rất khó vượt band 5.", "sections": [{"h": "4 dạng đề phổ biến", "html": "<table>\n<tr><th>Dạng</th><th>Câu hỏi thường gặp</th><th>Bạn phải làm</th></tr>\n<tr><td><b>Opinion</b> (ý kiến)</td><td><span class=\"en\">To what extent do you agree or disagree?</span></td><td>Nêu rõ đồng ý / không đồng ý và giải thích</td></tr>\n<tr><td><b>Discussion</b> (thảo luận 2 quan điểm)</td><td><span class=\"en\">Discuss both views and give your own opinion.</span></td><td>Trình bày CẢ hai quan điểm + ý kiến của bạn</td></tr>\n<tr><td><b>Advantages – Disadvantages</b></td><td><span class=\"en\">Do the advantages outweigh the disadvantages?</span></td><td>Nêu lợi, hại và nói bên nào lớn hơn</td></tr>\n<tr><td><b>Problem – Solution</b></td><td><span class=\"en\">What problems does this cause? What can be done?</span></td><td>Nêu vấn đề (hoặc nguyên nhân) và giải pháp</td></tr>\n</table>\n<div class=\"note\">Gạch chân câu hỏi cuối đề. Đề hỏi mấy ý thì phải trả lời đủ bấy nhiêu ý.</div>"}, {"h": "Bố cục 4 đoạn", "html": "<table>\n<tr><th>Đoạn</th><th>Nội dung</th></tr>\n<tr><td>1. Mở bài (2 câu)</td><td>Paraphrase đề + <b>thesis statement</b> (câu nêu quan điểm / nội dung bài sẽ viết)</td></tr>\n<tr><td>2. Thân bài 1 (4–6 câu)</td><td>Câu chủ đề → giải thích → ví dụ</td></tr>\n<tr><td>3. Thân bài 2 (4–6 câu)</td><td>Câu chủ đề → giải thích → ví dụ</td></tr>\n<tr><td>4. Kết bài (1–2 câu)</td><td>Nhắc lại quan điểm, tóm tắt ý chính, <b>không thêm ý mới</b></td></tr>\n</table>"}, {"h": "Ví dụ mở bài (dạng Opinion)", "html": "<div class=\"ex\">Đề: <span class=\"en\">Some people think children should learn to cook at school. To what extent do you agree or disagree?</span><br><br><span class=\"en\">It is often argued that cooking should be taught in schools. I completely agree with this view because it helps children eat more healthily and become more independent.</span><br><span class=\"vi\">Câu 1: paraphrase đề. Câu 2: thesis statement nêu rõ quan điểm và 2 lý do (= 2 thân bài).</span></div>"}], "tips": ["Dành 5 phút lập dàn ý: dạng đề, quan điểm, 2 ý chính, mỗi ý một ví dụ.", "Câu thesis nên báo trước 2 ý của 2 thân bài, giúp giám khảo dễ theo dõi.", "Giữ quan điểm nhất quán từ mở bài đến kết bài."], "mistakes": ["Dạng Discussion chỉ viết một quan điểm. Fix: phải trình bày cả hai quan điểm, rồi nêu ý kiến của mình.", "Đề yêu cầu ý kiến nhưng không nói rõ mình nghĩ gì. Fix: nêu quan điểm ngay trong mở bài.", "Thêm ý mới ở kết bài. Fix: kết bài chỉ tóm tắt lại ý đã viết.", "Viết dưới 250 từ. Fix: tập viết đủ 260–290 từ và đếm số từ trung bình mỗi dòng của mình."], "quiz": [{"q": "Đề: 'Some people think children should learn to cook at school. To what extent do you agree or disagree?' Đây là dạng gì?", "opts": ["Discussion", "Opinion", "Problem – Solution", "Advantages – Disadvantages"], "a": 1, "ex": "'To what extent do you agree or disagree?' là dấu hiệu của dạng Opinion."}, {"q": "Đề: 'Some believe working from home benefits employees, while others think it harms teamwork. Discuss both views and give your own opinion.' Đây là dạng gì?", "opts": ["Opinion", "Problem – Solution", "Discussion", "Advantages – Disadvantages"], "a": 2, "ex": "'Discuss both views and give your own opinion' là dạng Discussion: phải nói cả hai quan điểm và ý kiến riêng."}, {"q": "Đề: 'More people are buying products online. Do the advantages of this outweigh the disadvantages?' Đây là dạng gì?", "opts": ["Advantages – Disadvantages", "Discussion", "Problem – Solution", "Opinion"], "a": 0, "ex": "'Do the advantages outweigh the disadvantages?' là dạng Advantages – Disadvantages. Bạn phải nói rõ bên nào lớn hơn."}, {"q": "Đề: 'Traffic jams are getting worse in many cities. What are the causes, and what can be done to solve this problem?' Đây là dạng gì?", "opts": ["Opinion", "Discussion", "Advantages – Disadvantages", "Problem – Solution (nguyên nhân – giải pháp)"], "a": 3, "ex": "Đề hỏi nguyên nhân và giải pháp ('what can be done'), nên đây là dạng Problem/Cause – Solution."}, {"q": "Thesis statement (câu nêu quan điểm chính) thường nằm ở đâu?", "opts": ["Câu đầu tiên của thân bài 1", "Cuối đoạn mở bài", "Giữa thân bài 2", "Chỉ ở kết bài"], "a": 1, "ex": "Thesis statement thường là câu cuối của mở bài, sau câu paraphrase đề."}, {"q": "Kết bài của Task 2 nên làm gì?", "opts": ["Thêm một ý mới thật hay", "Đưa thêm ví dụ mới", "Nhắc lại quan điểm và tóm tắt ý chính", "Đặt câu hỏi cho giám khảo"], "a": 2, "ex": "Kết bài chỉ nhắc lại quan điểm và tóm tắt, không đưa ý hay ví dụ mới."}, {"q": "Với dạng Discussion, bài viết nào trả lời đúng yêu cầu?", "opts": ["Chỉ viết về quan điểm mình đồng ý", "Viết cả hai quan điểm nhưng không nêu ý kiến riêng", "Chỉ viết ý kiến riêng", "Viết cả hai quan điểm và nêu rõ ý kiến riêng"], "a": 3, "ex": "Đề yêu cầu 'discuss both views AND give your own opinion', nên phải có đủ cả hai phần."}, {"q": "Task 2 yêu cầu ít nhất bao nhiêu từ?", "opts": ["250 từ", "150 từ", "200 từ", "300 từ"], "a": 0, "ex": "Task 2 tối thiểu 250 từ. Viết thiếu sẽ bị ảnh hưởng điểm Task Response."}]}, {"id": "ielts-tu-noi-paraphrase", "group": "Viết", "title": "Từ nối và paraphrase", "level": 2, "mins": 15, "why": "Từ nối dùng đúng giúp tăng điểm Coherence and Cohesion trong Writing, còn paraphrase là kỹ năng dùng ở mở bài Writing và giúp nhận ra đáp án trong Listening, Reading (đề luôn dùng từ đồng nghĩa).", "sections": [{"h": "Từ nối theo chức năng", "html": "<table>\n<tr><th>Chức năng</th><th>Từ nối</th><th>Ví dụ</th></tr>\n<tr><td>Thêm ý</td><td>Moreover, In addition, Furthermore</td><td><span class=\"en\">In addition, cycling reduces pollution.</span></td></tr>\n<tr><td>Đối lập</td><td>However, On the other hand / although, while</td><td><span class=\"en\">However, it can be dangerous.</span></td></tr>\n<tr><td>Kết quả</td><td>Therefore, As a result / so</td><td><span class=\"en\">As a result, many people moved.</span></td></tr>\n<tr><td>Nguyên nhân</td><td>because + mệnh đề / because of, due to + danh từ</td><td><span class=\"en\">because of the rain</span></td></tr>\n<tr><td>Ví dụ</td><td>For example, For instance / such as + danh từ</td><td><span class=\"en\">such as buses and trains</span></td></tr>\n<tr><td>Kết luận</td><td>In conclusion, To sum up</td><td><span class=\"en\">In conclusion, ...</span></td></tr>\n</table>"}, {"h": "Cẩn thận ngữ pháp của từ nối", "html": "<table>\n<tr><th>Từ</th><th>Theo sau là</th><th>Ví dụ</th></tr>\n<tr><td>However,</td><td>đứng đầu câu mới, có dấu phẩy</td><td><span class=\"en\">It is cheap. However, it is slow.</span></td></tr>\n<tr><td>Although / Because</td><td>mệnh đề (S + V)</td><td><span class=\"en\">Although it was expensive, ...</span></td></tr>\n<tr><td>Despite / Because of</td><td>danh từ hoặc V-ing</td><td><span class=\"en\">Despite the high price, ...</span></td></tr>\n</table>"}, {"h": "3 cách paraphrase", "html": "<table>\n<tr><th>Cách</th><th>Câu gốc</th><th>Paraphrase</th></tr>\n<tr><td>1. Từ đồng nghĩa</td><td><span class=\"en\">Many young people use social media.</span></td><td><span class=\"en\">A large number of teenagers use social networks.</span></td></tr>\n<tr><td>2. Đổi từ loại</td><td><span class=\"en\">Cars pollute the air.</span> (động từ)</td><td><span class=\"en\">Cars cause air pollution.</span> (danh từ)</td></tr>\n<tr><td>3. Đổi cấu trúc</td><td><span class=\"en\">The government built a new hospital.</span> (chủ động)</td><td><span class=\"en\">A new hospital was built by the government.</span> (bị động)</td></tr>\n</table>\n<div class=\"note\">Paraphrase tốt = <b>giữ nguyên nghĩa</b>. Đổi từ mà làm sai nghĩa (young → old, many → all) là paraphrase sai.</div>"}], "tips": ["Mỗi chức năng học chắc 2 từ nối là đủ, dùng đúng quan trọng hơn dùng nhiều.", "Kết hợp 2 cách paraphrase trong một câu (đồng nghĩa + đổi cấu trúc) để câu tự nhiên hơn.", "Khi đọc đề Reading/Listening, thử đoán đề sẽ paraphrase từ khóa thế nào."], "mistakes": ["Viết 'Although..., but...'. Fix: chỉ dùng một từ: 'Although it rained, we went out.'", "Dùng 'Despite' + mệnh đề: 'Despite it was expensive'. Fix: 'Despite the high price' hoặc 'Although it was expensive'.", "Câu nào cũng mở đầu bằng từ nối (Moreover, Furthermore...). Fix: dùng vừa đủ, có câu không cần từ nối.", "Dùng từ đồng nghĩa sai ngữ cảnh khi tra từ điển. Fix: chỉ dùng từ mà bạn đã thấy trong câu ví dụ."], "quiz": [{"q": "Public transport is cheap. ____, it is often crowded.", "opts": ["Moreover", "However", "For example", "Therefore"], "a": 1, "ex": "Câu sau nêu điểm trừ trái với câu trước (rẻ nhưng đông), nên dùng 'However'."}, {"q": "She stayed at home ____ the heavy rain.", "opts": ["because", "although", "because of", "so"], "a": 2, "ex": "Sau chỗ trống là cụm danh từ 'the heavy rain', nên dùng 'because of'. 'because' phải đi với mệnh đề (S + V)."}, {"q": "Exercise improves your health. ____, it reduces stress.", "opts": ["In addition", "However", "Although", "As a result of"], "a": 0, "ex": "Câu sau thêm một lợi ích nữa, nên dùng từ thêm ý 'In addition'."}, {"q": "____ the price was high, many people bought the phone.", "opts": ["Despite", "However", "Because of", "Although"], "a": 3, "ex": "Sau chỗ trống là mệnh đề 'the price was high' (S + V), và ý đối lập, nên dùng 'Although'. 'Despite' phải đi với danh từ."}, {"q": "Câu nào paraphrase đúng nghĩa câu: 'Many young people spend too much time on social media.'?", "opts": ["Young people never use social media.", "Many old people spend time on social media.", "A large number of teenagers use social media excessively.", "Social media spends young people."], "a": 2, "ex": "Câu C thay 'many young people' → 'a large number of teenagers', 'spend too much time' → 'use excessively', giữ nguyên nghĩa. Các câu khác đổi sai nghĩa hoặc sai ngữ pháp."}, {"q": "Danh từ của động từ 'pollute' là gì (dùng khi paraphrase bằng cách đổi từ loại)?", "opts": ["polluting", "polluted", "pollutes", "pollution"], "a": 3, "ex": "'pollution' (sự ô nhiễm) là danh từ. Ví dụ: 'Cars pollute the air' → 'Cars cause air pollution'."}, {"q": "'The government built a new hospital.' → 'A new hospital was built by the government.' Đây là cách paraphrase nào?", "opts": ["Đổi cấu trúc (chủ động → bị động)", "Từ đồng nghĩa", "Đổi từ loại", "Không phải paraphrase"], "a": 0, "ex": "Câu chuyển từ chủ động sang bị động, nghĩa giữ nguyên: đây là đổi cấu trúc."}, {"q": "Cars are expensive to buy. ____, many families cannot afford one.", "opts": ["For example", "As a result", "Although", "On the other hand"], "a": 1, "ex": "Câu sau là kết quả của câu trước (xe đắt → nhiều gia đình không mua nổi), nên dùng 'As a result'."}]}, {"id": "ielts-speaking-part-1-3", "group": "Nói", "title": "Speaking Part 1–3: trả lời thế nào", "level": 1, "mins": 14, "why": "Speaking kéo dài 11–14 phút với 3 phần có yêu cầu khác nhau. Trả lời quá ngắn ('Yes.', 'No.') là lý do phổ biến nhất khiến người mới bị kẹt ở band 4.5–5.0 Fluency.", "sections": [{"h": "Tổng quan 3 phần", "html": "<table>\n<tr><th>Phần</th><th>Thời gian</th><th>Nội dung</th><th>Độ dài câu trả lời</th></tr>\n<tr><td>Part 1</td><td>4–5 phút</td><td>Câu hỏi quen thuộc: quê, công việc, sở thích</td><td>2–3 câu</td></tr>\n<tr><td>Part 2</td><td>3–4 phút</td><td>Thẻ đề (cue card): 1 phút chuẩn bị, nói 1–2 phút</td><td>nói liên tục đến khi giám khảo dừng</td></tr>\n<tr><td>Part 3</td><td>4–5 phút</td><td>Thảo luận vấn đề chung, trừu tượng liên quan đến Part 2</td><td>3–5 câu</td></tr>\n</table>"}, {"h": "Part 1: Trả lời + Lý do + Ví dụ", "html": "<div class=\"ex\">Q: <span class=\"en\">Do you like cooking?</span><br>\n<b>Trả lời:</b> <span class=\"en\">Yes, I do.</span><br>\n<b>Lý do:</b> <span class=\"en\">It helps me relax after a long day.</span><br>\n<b>Ví dụ:</b> <span class=\"en\">For example, last Sunday I made spring rolls for my family.</span></div>\n<p>Không cần nói quá dài. 2–3 câu tự nhiên là đẹp nhất cho Part 1.</p>"}, {"h": "Part 2: Ghi chú trong 1 phút", "html": "<div class=\"ex\">Đề: <span class=\"en\">Describe a trip you took last year. You should say: where you went, who you went with, what you did, and explain how you felt.</span><br><br>Ghi chú (chỉ từ khóa):<br>Da Lat – Dec<br>3 friends, uni<br>flower garden, coffee, night market<br>relaxed, cold, want to return</div>\n<ul>\n<li>Viết <b>từ khóa</b>, không viết câu hoàn chỉnh.</li>\n<li>Đi theo thứ tự các gợi ý trên thẻ.</li>\n<li>Sự việc đã xảy ra → dùng <b>thì quá khứ</b> (<span class=\"en\">went, visited, felt</span>).</li>\n</ul>"}, {"h": "Part 3: Nêu quan điểm và giải thích", "html": "<p>Công thức: <b>Quan điểm → Lý do → Ví dụ / So sánh</b>.</p>\n<div class=\"ex\">Q: <span class=\"en\">Why do young people prefer shopping online?</span><br>\n<span class=\"en\">I think the main reason is convenience. Young people are busy, so they can order things at any time on their phones. For instance, my cousin buys almost everything through apps. However, older people often prefer to see products before buying.</span></div>\n<p>Cụm hữu ích: <span class=\"en\">I think / In my opinion / The main reason is... / It depends on...</span></p>"}], "tips": ["Không hiểu câu hỏi thì cứ hỏi lại: 'Sorry, could you say that again, please?' Không bị trừ điểm.", "Cần thời gian suy nghĩ, dùng: 'That's an interesting question. Let me think...' thay vì im lặng.", "Không học thuộc bài mẫu. Giám khảo dễ nhận ra và bài nói nghe không tự nhiên."], "mistakes": ["Trả lời một từ: 'Yes.' Fix: luôn thêm lý do và (nếu được) một ví dụ.", "Part 2 viết cả câu khi ghi chú, hết 1 phút mới xong 2 ý. Fix: chỉ ghi từ khóa.", "Part 2 kể chuyện đã qua nhưng dùng thì hiện tại ('I go to Da Lat'). Fix: dùng quá khứ (I went).", "Part 3 chỉ nói về bản thân. Fix: nói về người nói chung (young people, many families) và xã hội."], "quiz": [{"q": "Part 1 – 'Do you like cooking?' Câu trả lời nào tốt nhất?", "opts": ["Yes.", "Yes, I do. I usually cook on weekends because it helps me relax. For example, last Sunday I made pho for my family.", "I don't know.", "Cooking is an activity of preparing food by heating it, and it has a long history..."], "a": 1, "ex": "Câu B có đủ: trả lời + lý do + ví dụ, độ dài vừa phải. Câu A quá ngắn, câu D lan man như học thuộc."}, {"q": "Trong Part 2, bạn có bao lâu để chuẩn bị?", "opts": ["Không có", "30 giây", "1 phút", "3 phút"], "a": 2, "ex": "Giám khảo đưa thẻ đề, giấy và bút, bạn có 1 phút để ghi chú."}, {"q": "Trong Part 2, bạn nên nói trong khoảng bao lâu?", "opts": ["10–20 giây", "1–2 phút", "5 phút", "10 phút"], "a": 1, "ex": "Bạn nói khoảng 1–2 phút. Hãy cố nói đến khi giám khảo dừng bạn."}, {"q": "Khi ghi chú trong 1 phút ở Part 2, nên viết gì?", "opts": ["Từ khóa ngắn cho từng gợi ý trên thẻ", "Cả bài nói hoàn chỉnh", "Không cần ghi gì", "Dịch đề ra tiếng Việt"], "a": 0, "ex": "1 phút chỉ đủ để ghi từ khóa. Từ khóa giúp bạn nhớ ý mà vẫn nói tự nhiên."}, {"q": "Part 3 – 'Why do young people prefer shopping online?' Cách mở đầu nào tốt nhất?", "opts": ["Yes.", "I don't like shopping.", "Online.", "I think the main reason is convenience, because..."], "a": 3, "ex": "Part 3 cần nêu quan điểm rồi giải thích. 'I think the main reason is... because...' là mở đầu tốt."}, {"q": "Bạn không hiểu câu hỏi của giám khảo. Nên làm gì?", "opts": ["Im lặng chờ câu tiếp theo", "Nói một chủ đề khác", "Hỏi lại: 'Sorry, could you say that again, please?'", "Trả lời bằng tiếng Việt"], "a": 2, "ex": "Hỏi lại là hoàn toàn bình thường và không bị trừ điểm."}, {"q": "Đề Part 2: 'Describe a trip you took last year.' Bạn nên dùng thì gì chủ yếu?", "opts": ["Quá khứ đơn (went, visited)", "Hiện tại đơn (go, visit)", "Tương lai (will go)", "Hiện tại tiếp diễn (am going)"], "a": 0, "ex": "Chuyến đi đã xảy ra năm ngoái (last year), nên kể bằng thì quá khứ đơn."}, {"q": "Câu hỏi Part 3 thường khác Part 1 ở điểm nào?", "opts": ["Dễ hơn và về bản thân", "Về vấn đề chung, trừu tượng của xã hội", "Chỉ hỏi Yes/No", "Không liên quan đến Part 2"], "a": 1, "ex": "Part 3 thảo luận vấn đề chung, liên quan đến chủ đề Part 2, nên cần nêu quan điểm và giải thích sâu hơn."}]}, {"id": "ielts-cau-phuc-band-6", "group": "Ngữ pháp", "title": "Câu phức cho band 6+", "level": 2, "mins": 15, "why": "Để đạt band 6 tiêu chí Grammatical Range and Accuracy trong Writing và Speaking, bạn cần dùng được câu phức (mệnh đề quan hệ, although, if, bị động) chứ không chỉ câu đơn.", "sections": [{"h": "Mệnh đề quan hệ", "html": "<table>\n<tr><th>Từ</th><th>Thay cho</th><th>Ví dụ</th></tr>\n<tr><td>who</td><td>người</td><td><span class=\"en\">People who exercise regularly sleep better.</span></td></tr>\n<tr><td>which</td><td>vật, sự việc</td><td><span class=\"en\">Cars which use less fuel are popular.</span></td></tr>\n<tr><td>where</td><td>nơi chốn</td><td><span class=\"en\">This is the town where I grew up.</span></td></tr>\n<tr><td>whose</td><td>của ai</td><td><span class=\"en\">Students whose parents read to them often enjoy books.</span></td></tr>\n</table>\n<div class=\"note\">Mệnh đề có dấu phẩy (bổ sung thông tin): dùng <b>who / which</b>, <b>không</b> dùng <b>that</b>.<br><span class=\"en\">Hanoi, which is the capital of Vietnam, has many lakes.</span></div>"}, {"h": "Although / While: đối lập trong một câu", "html": "<div class=\"ex\"><span class=\"en\">Although online learning is flexible, it requires a lot of self-discipline.</span><br><span class=\"vi\">Mặc dù học online linh hoạt, nó đòi hỏi tính tự giác cao.</span><br><br><span class=\"en\">While some people prefer living in cities, others enjoy the countryside.</span><br><span class=\"vi\">Trong khi một số người thích sống ở thành phố, những người khác lại thích nông thôn.</span></div>"}, {"h": "Câu điều kiện (if)", "html": "<table>\n<tr><th>Loại</th><th>Công thức</th><th>Ví dụ</th></tr>\n<tr><td>Loại 1 (có thể xảy ra)</td><td>If + hiện tại đơn, will + V</td><td><span class=\"en\">If the government raises taxes on fast food, people will eat more healthily.</span></td></tr>\n<tr><td>Loại 2 (giả định, khó xảy ra)</td><td>If + quá khứ đơn, would + V</td><td><span class=\"en\">If more people used bicycles, the air would be cleaner.</span></td></tr>\n</table>"}, {"h": "Câu bị động trong Writing", "html": "<p>Công thức: <b>be + V3 (past participle)</b>. Dùng khi hành động quan trọng hơn người làm.</p>\n<table>\n<tr><th>Dùng ở</th><th>Ví dụ</th></tr>\n<tr><td>Task 1 (quy trình)</td><td><span class=\"en\">The tea leaves are picked by hand and then dried.</span></td></tr>\n<tr><td>Task 2 (khách quan)</td><td><span class=\"en\">It is widely believed that technology makes life easier.</span></td></tr>\n<tr><td>Task 1 (quá khứ)</td><td><span class=\"en\">About 2 million tonnes of rice were exported in 2015.</span></td></tr>\n</table>"}], "tips": ["Mỗi đoạn thân bài Task 2 nên có ít nhất 1 câu phức, nhưng đừng cố nhồi câu quá dài.", "Ưu tiên câu đúng hơn câu khó: một câu phức đúng tốt hơn ba câu phức sai.", "Task 1 dạng quy trình (process) gần như bắt buộc dùng bị động hiện tại."], "mistakes": ["Dùng 'which' cho người: 'the students which passed'. Fix: người → who.", "Dùng 'that' sau dấu phẩy: 'Hanoi, that is the capital...'. Fix: dùng 'which'.", "Câu điều kiện loại 1 dùng 'will' sau 'if': 'If it will rain...'. Fix: 'If it rains, ...'.", "Bị động thiếu 'be': 'The leaves picked by hand.' Fix: 'The leaves are picked by hand.'"], "quiz": [{"q": "People ____ exercise regularly tend to sleep better.", "opts": ["which", "who", "where", "whose"], "a": 1, "ex": "'People' là người, nên dùng 'who'."}, {"q": "Ho Chi Minh City, ____ is the largest city in Vietnam, has heavy traffic.", "opts": ["that", "who", "which", "where"], "a": 2, "ex": "Thay cho thành phố (vật/nơi) làm chủ ngữ của 'is', và có dấu phẩy nên dùng 'which', không dùng 'that'. 'where' không đứng trước động từ 'is' như chủ ngữ được."}, {"q": "____ the job is well paid, it is very stressful.", "opts": ["Although", "Because", "If", "So"], "a": 0, "ex": "Hai ý đối lập (lương cao nhưng căng thẳng) nên dùng 'Although'."}, {"q": "If more people ____ bicycles, the air would be cleaner.", "opts": ["use", "will use", "using", "used"], "a": 3, "ex": "Vế sau có 'would be' → câu điều kiện loại 2, vế 'if' dùng quá khứ đơn: 'used'."}, {"q": "If the government ____ taxes on fast food, people will eat more healthily.", "opts": ["raise", "raises", "will raise", "raised"], "a": 1, "ex": "Vế sau có 'will' → điều kiện loại 1, vế 'if' dùng hiện tại đơn. 'the government' là số ít nên là 'raises'."}, {"q": "In this process, the tea leaves ____ by hand.", "opts": ["pick", "are picking", "are picked", "picked"], "a": 2, "ex": "Lá trà không tự hái, chúng 'được hái' → bị động: are + V3 = 'are picked'."}, {"q": "This is the village ____ my grandparents grew up.", "opts": ["where", "which", "who", "whose"], "a": 0, "ex": "Chỉ nơi chốn và vế sau đã đủ chủ ngữ + động từ (my grandparents grew up), nên dùng 'where'."}, {"q": "Tìm lỗi sai: 'The students which passed the test received a certificate.'", "opts": ["passed", "received", "the test", "which"], "a": 3, "ex": "'students' là người nên phải dùng 'who' (hoặc 'that'), không dùng 'which'."}]}, {"id": "ielts-loi-ngu-phap-nguoi-viet", "group": "Ngữ pháp", "title": "Lỗi ngữ pháp người Việt hay mắc", "level": 1, "mins": 12, "why": "Tiếng Việt không có mạo từ, số nhiều hay chia động từ, nên người Việt rất hay mắc các lỗi này trong Writing và Speaking. Lỗi lặp đi lặp lại kéo điểm Grammatical Accuracy xuống dưới band 6.", "sections": [{"h": "Mạo từ a / an / the", "html": "<table>\n<tr><th>Lỗi</th><th>Sửa</th><th>Quy tắc</th></tr>\n<tr><td>I am student.</td><td>I am <b>a</b> student.</td><td>danh từ đếm được số ít cần a/an</td></tr>\n<tr><td>He is a engineer.</td><td>He is <b>an</b> engineer.</td><td>an + âm nguyên âm (a, e, i, o, u)</td></tr>\n<tr><td>Sun is very hot today.</td><td><b>The</b> sun is very hot today.</td><td>the + vật duy nhất / đã biết</td></tr>\n</table>"}, {"h": "Số nhiều", "html": "<table>\n<tr><th>Lỗi</th><th>Sửa</th><th>Ghi chú</th></tr>\n<tr><td>many book</td><td>many book<b>s</b></td><td>many, a lot of, some + số nhiều</td></tr>\n<tr><td>one of my friend</td><td>one of my friend<b>s</b></td><td>one of + số nhiều</td></tr>\n<tr><td>informations, advices</td><td>information, advice</td><td>danh từ không đếm được, không thêm -s</td></tr>\n</table>"}, {"h": "Chia động từ", "html": "<table>\n<tr><th>Lỗi</th><th>Sửa</th><th>Quy tắc</th></tr>\n<tr><td>She go to work by bus.</td><td>She go<b>es</b> ...</td><td>he/she/it + V-s/es (hiện tại đơn)</td></tr>\n<tr><td>Yesterday I go to the market.</td><td>Yesterday I <b>went</b> ...</td><td>yesterday, last year → quá khứ</td></tr>\n<tr><td>The number of tourists have increased.</td><td>... <b>has</b> increased.</td><td>chủ ngữ chính là \"the number\" (số ít)</td></tr>\n</table>"}, {"h": "Thiếu hoặc thừa 'be' và There is / are", "html": "<table>\n<tr><th>Lỗi</th><th>Sửa</th><th>Ghi chú</th></tr>\n<tr><td>My brother very tall.</td><td>My brother <b>is</b> very tall.</td><td>trước tính từ cần \"be\"</td></tr>\n<tr><td>I am agree.</td><td>I agree.</td><td>\"agree\" là động từ, không cần \"am\"</td></tr>\n<tr><td>Have many people in the park.</td><td><b>There are</b> many people in the park.</td><td>\"có\" (tồn tại) = there is / there are</td></tr>\n<tr><td>There is many reasons.</td><td>There <b>are</b> many reasons.</td><td>there are + số nhiều; there is + số ít / không đếm được</td></tr>\n</table>"}], "tips": ["Viết xong, dành 3 phút soát riêng 3 lỗi: thiếu -s, thiếu a/the, sai thì động từ.", "Ghi lại lỗi mình hay mắc vào một danh sách nhỏ và đọc lại trước mỗi lần viết.", "Khi nói, nói chậm một chút để kịp thêm -s và -ed: chính xác quan trọng hơn nhanh."], "mistakes": ["Dịch từng chữ 'Có nhiều người...' thành 'Have many people...'. Fix: dùng 'There are many people...'.", "Thêm 'am/is' trước động từ: 'I am agree', 'She is work here'. Fix: 'I agree', 'She works here'.", "Quên -s với he/she/it, đặc biệt khi nói. Fix: luyện nói chậm các câu về người thứ ba.", "Thêm -s cho information, advice, equipment. Fix: học thuộc nhóm danh từ không đếm được thường gặp."], "quiz": [{"q": "Tìm câu đúng ngữ pháp.", "opts": ["My brother very tall.", "My brother is very tall.", "My brother are very tall.", "My brother tall very."], "a": 1, "ex": "Trước tính từ 'tall' cần động từ 'be'. 'My brother' là số ít nên dùng 'is'."}, {"q": "____ many shops near my house.", "opts": ["Have", "There is", "There are", "It has"], "a": 2, "ex": "'Có' (tồn tại) dùng 'there is/are'. 'many shops' số nhiều nên là 'There are'."}, {"q": "She ____ to work by bus every day.", "opts": ["go", "goes", "going", "is go"], "a": 1, "ex": "Hiện tại đơn với 'she' thì động từ thêm -es: 'goes'."}, {"q": "I need some ____ about the course.", "opts": ["informations", "information", "an information", "many information"], "a": 1, "ex": "'information' là danh từ không đếm được, không thêm -s và không dùng 'an' hay 'many'."}, {"q": "I ____ with this opinion.", "opts": ["agree", "am agree", "agreeing", "am agreed"], "a": 0, "ex": "'agree' đã là động từ, không cần 'am'. Câu đúng: 'I agree with this opinion.'"}, {"q": "He is ____ engineer.", "opts": ["a", "the", "Không cần mạo từ", "an"], "a": 3, "ex": "'engineer' bắt đầu bằng âm nguyên âm /e/, nên dùng 'an'."}, {"q": "Last summer, my family ____ to Da Lat.", "opts": ["go", "goes", "went", "going"], "a": 2, "ex": "'Last summer' là thời gian đã qua → quá khứ đơn: 'went'."}, {"q": "Tìm lỗi sai: 'There is many reasons why people move to cities.'", "opts": ["is", "reasons", "why", "move"], "a": 0, "ex": "'many reasons' là số nhiều, nên phải là 'There are', không phải 'There is'."}]}];
